-- db_info: data informasi publik (harga pangan + produksi per provinsi) untuk layanan-info
CREATE DATABASE IF NOT EXISTS db_info CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE USER IF NOT EXISTS 'user_info'@'%' IDENTIFIED BY 'infoTani2026';
GRANT ALL PRIVILEGES ON db_info.* TO 'user_info'@'%';
FLUSH PRIVILEGES;
USE db_info;

CREATE TABLE IF NOT EXISTS harga_pangan (
  id INT AUTO_INCREMENT PRIMARY KEY,
  komoditas VARCHAR(60) NOT NULL,
  varian VARCHAR(80) NOT NULL DEFAULT '-',
  tingkat ENUM('Petani','Grosir','Konsumen') NOT NULL DEFAULT 'Konsumen',
  wilayah VARCHAR(60) NOT NULL DEFAULT 'Nasional',
  periode CHAR(7) NOT NULL,                 -- format YYYY-MM
  harga DECIMAL(12,2) NOT NULL,
  satuan VARCHAR(10) NOT NULL DEFAULT 'kg',
  sumber VARCHAR(200) NOT NULL DEFAULT '-',
  diperbarui_oleh VARCHAR(100) NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uk_harga (komoditas, varian, tingkat, wilayah, periode)
);

CREATE TABLE IF NOT EXISTS produksi_provinsi (
  id INT AUTO_INCREMENT PRIMARY KEY,
  provinsi VARCHAR(60) NOT NULL,
  komoditas VARCHAR(40) NOT NULL,
  tahun SMALLINT NOT NULL,
  produksi_ton DECIMAL(14,2) NOT NULL,
  luas_panen_ha DECIMAL(14,2) NULL,
  sumber VARCHAR(200) NOT NULL,
  UNIQUE KEY uk_prod (provinsi, komoditas, tahun)
);



-- Tambahan 2026-11-17: tingkat Produsen + data Panel Harga Bapanas (diambil manual dari situs, diekspor CSV)
USE db_info;
ALTER TABLE harga_pangan MODIFY tingkat ENUM('Petani','Produsen','Grosir','Konsumen') NOT NULL DEFAULT 'Konsumen';
